const PROJECTS_KEY='izdelie-projects-v5';
const projectNormal=s=>String(s).trim().replace(/\s+/g,' ');
function projects(){const extra=readJSON(PROJECTS_KEY,{}),all=new Map();for(const name of PROJECT_SEED){const n=projectNormal(name);all.set(n.toLowerCase(),n)}for(const name of Object.keys(extra||{})){const n=projectNormal(name);if(n)all.set(n.toLowerCase(),n)}return [...all.values()].sort((a,b)=>a.localeCompare(b,'ru'))}
function projectCard(){return `<details class="card"><summary>Проект: ${esc(state.projectName||'без привязки')}</summary><div class="cardhead"><h2>Проект из реестра</h2><button onclick="go(18)">Реестр →</button></div><div class="field"><label for="projectSearch">Поиск по названию, подразделению или объекту</label><input id="projectSearch" placeholder="Например: Мордовцева опалубка" oninput="projectOptions()"></div><div id="projectOptions"></div><p class="small">Выбран: <b>${esc(state.projectName||'Без привязки к проекту')}</b></p><div class="mini-actions"><button onclick="chooseProject('')">Снять привязку</button><button onclick="addProjectDialog()">＋ Новый проект</button></div><p class="small">Проект сохраняется вместе с версией расчёта. Артикул изделия и заказчик заполняются независимо.</p></details>`}
function projectOptions(){if(!$('projectOptions'))return;const q=($('projectSearch')?.value||'').toLowerCase(),a=projects().filter(n=>q.split(/\s+/).every(w=>n.toLowerCase().includes(w)));$('projectOptions').innerHTML=`<div class="field"><label for="projectSelect">Проект (${a.length})</label><select id="projectSelect" onchange="chooseProject(this.value)"><option value="">Выберите проект…</option>${a.map(n=>`<option value="${esc(n)}" ${state.projectName===n?'selected':''}>${esc(n)}</option>`).join('')}</select></div>`}
function chooseProject(name){if(name&&!projects().includes(name))return;state.projectName=name;persist();render()}
function addProjectDialog(){modal('Добавить проект',`<div class="field"><label for="newProjectName">Полное название проекта</label><input id="newProjectName" placeholder="26 - MSKV - Объект - ПОСТ"></div><button class="primary" onclick="commitProject()">Добавить и привязать</button>`)}
function commitProject(){const name=projectNormal($('newProjectName').value);if(!name||name.length>500){toast('Введите название до 500 символов');return}const existing=projects().find(n=>n.toLowerCase()===name.toLowerCase());if(!existing){const a=readJSON(PROJECTS_KEY,{});a[name]={createdAt:stamp()};if(!writeJSON(PROJECTS_KEY,a))return}state.projectName=existing||name;persist();$('modal').close();render();toast('Проект выбран')}
function renderProjects(){$('app').innerHTML=title('Данные / Проекты','Реестр проектов','Проекты из вашего списка и связанные сохранённые расчёты.','Выбор проекта')+`<div class="toolbar"><input id="registrySearch" placeholder="Поиск проекта…" oninput="projectRows()"><select id="registryYear" onchange="projectRows()"><option value="">Все годы</option>${[...new Set(projects().map(n=>n.split(' - ')[0]))].map(y=>`<option>${esc(y)}</option>`).join('')}</select><button onclick="addProjectDialog()">＋ Проект</button></div><div class="card"><div id="registryRows"></div></div>`;projectRows()}
function projectRows(){const q=$('registrySearch').value.toLowerCase(),year=$('registryYear').value,all=projects().filter(n=>(!year||n.startsWith(year+' - '))&&q.split(/\s+/).every(w=>n.toLowerCase().includes(w))),lib=library();$('registryRows').innerHTML=`<p class="small">${all.length} проектов. Повторы и лишние пробелы объединены; этапы и номера поставок сохранены.</p><div class="tablewrap"><table><thead><tr><th>Проект</th><th>Изделия</th><th></th></tr></thead><tbody>${all.map(n=>{const related=lib.filter(e=>e.revisions.at(-1).calculation.projectName===n);return `<tr><td>${esc(n)}${state.projectName===n?'<span class="source">Выбран в текущем расчёте</span>':''}</td><td>${related.length?related.map(e=>`<button class="textbutton" onclick="libraryDetail('${e.id}')">${esc(e.name)}</button>`).join('<br>'):'—'}</td><td><button onclick="chooseProject(${esc(JSON.stringify(n))});go(0)">Выбрать</button></td></tr>`}).join('')}</tbody></table></div>`}
function addDesign(){const l=lineFrom();Object.assign(l,{kind:'work',name:'Проектирование',unit:'чел·ч',group:'Проектирование',costCategory:'design',scope:'batch',qty:null,price:null,reserve:0,pack:1,source:'Ручной ввод трудоёмкости проектирования и ставки'});pendingNewLine=l;editLine(l.id)}
render();
